WITH base AS (SELECT * FROM order_items WHERE order_id = 12), summary AS (SELECT CASE WHEN quantity >= 7 THEN 'high' WHEN quantity >= 3 THEN 'mid' ELSE 'low' END AS quantity_bucket, product_id, SUM(unit_price) AS total_unit_price FROM base GROUP BY CASE WHEN quantity >= 7 THEN 'high' WHEN quantity >= 3 THEN 'mid' ELSE 'low' END, product_id) SELECT quantity_bucket, product_id, total_unit_price FROM summary ORDER BY 2, quantity_bucket LIMIT 1;
